import { useEffect } from "react";
import { useChatStore } from "@/lib/store/chat-store";

export type ChatMessage = {
  role: "bot" | "user";
  content: string;
  solutions?: any[];
};

export function useChat() {
  const {
    messages,
    setMessages,
    addMessage,
    clearMessages,
    updateActivity,
    isSessionValid,
  } = useChatStore();

  // Check session validity on mount and clear if expired
  useEffect(() => {
    if (!isSessionValid()) {
      clearMessages();
    }
  }, [clearMessages, isSessionValid]);

  return {
    messages,
    setMessages,
    addMessage,
    clearMessages,
    updateActivity,
  };
}
